<template><view class="page"><text class="title">我的听书账号</text><template v-if="store.token"><text>{{store.user.nickname}}</text><text class="hint">账号编号 {{store.user.id}}</text><text class="hint">{{store.user.isVip===1?'VIP 会员':'普通会员'}}{{store.user.vipExpireTime?' · 到期 '+store.user.vipExpireTime:''}}</text><button @click="go('/pages/business/business')">我的订单与售后</button><button @click="go('/pages/knowledge/knowledge')">我的知识空间</button><button @click="openAssistant()">听见助手</button><button class="secondary" @click="logout">退出登录</button></template><button v-else @click="go('/pages/login/login')">账号登录 / 注册</button><text class="hint">{{error}}</text><button class="secondary" @click="go('/pages/index/index')">返回首页</button></view></template>
<script setup lang="ts">
import {openAssistant} from "../../stores/assistant"

import {ref} from 'vue';import {onShow} from '@dcloudio/uni-app';import {useUserStore} from '../../stores/user';const store=useUserStore(),error=ref('');function go(url:string){uni.navigateTo({url})}async function logout(){await store.logout()}onShow(async()=>{if(store.token)try{await store.getUserInfo()}catch(e:any){error.value=e.message}});
